"""
        Makes an object list out of cybox objects to put in a cybox container
    """
def make_cybox_object_list(objects: Any) -> object {
    cybox_objects = {};
    for i in range(len(objects)) {
        cybox_objects[str(i)] = objects[i];
    }
    return cybox_objects;
}

